      "q": "七年四班的同學在電視上看到一則新聞報導，標題為「臺南鄭成功祖廟進行誕辰祭祀典禮，臺南市長擔任主祭官，鄭氏宗親與原住民族都抗議！」以下為記者對於鄭氏宗親與原住民族的訪談資料。\n甲：以往的祭祀都由中央政府代表國家舉行祭拜典禮，今年卻改由地方首長來主持，我感到非常遺憾。鄭成功被稱為開臺聖王，他請走荷蘭人，勇敢的反清復明、保衛國家，影響臺灣深遠，鄭成功祭典是國家大事，應由中央政府主持。\n乙：政府應該要正視鄭成功迫害平埔族的歷史，他趕走荷蘭人，卻延續荷蘭人的壓迫，甚至更加殘暴，他一路從臺南西拉雅族殺到中部的巴布拉族、道卡斯族。請政府重視鄭氏政權對平埔族的屠殺，希望國家不要再祭拜鄭成功了。\n根據甲與乙雙方的說法，下列哪一位同學的解讀最為適當？",
