      "points": 2,
      "group": "巴達維亞城日記中記載，西元1614年4月□□人擒獲中國海盜時，從海盜口中聽聞馬芝遴(Betgirem，今鹿港一帶)與淡水之間，存在著22個村落，其中18個村落被稱為Quataong的領袖所統治。十七世紀時，John Struys以「全臺最富庶之處」描述「大肚王」的轄區，特別是大肚台地西側平原——即「大肚王」所屬的巴布拉族主要地理分布區；據載，各種穀物、瓜果、蔬菜應有盡有。David Wright對此地也是讚美有佳，特別是牛罵社，係全臺唯一被譽為美麗之處。西元1661年，鄭成功企圖從□□手上奪取台灣，大肚王國頑強抵抗鄭軍，導致鄭成功等人認為他們受到□□的煽動。實際上由於鄭軍當時尚未攻下安平就已缺糧，因此下令前往北屯墾，就地取糧或種植，因此與大肚王國諸社發生激烈衝突。",
