      "group": "【閱讀測驗（一）】\n世界上從來成功的條件是把握時間、空間、數字，一分一秒地爭，尺地寸土地爭，一分一釐地爭。大禹惜寸陰、陶侃惜分陰，是爭了時間。「寧可進尺，不可退寸」、「去此一步無死所」是爭了空間。小數點下算到多少位，度量衡找世界的標準，都是爭了極小的數字。科學、工業化、機械化的現代，把時間、空間、數字分析得更精密，應用得更正確。\n精密的機器，產生於精密的思想、精密的技術。科學化的工業管理，機械運用，產生於科學化的人生態度。差不多先生不但為自己帶來許多災難，對於推進國家民族的現代化、工業機械化，也是格格不入的，幸而差不多先生早早死了。如果我們為這圓通大師補個墓銘應當說：「差之毫釐，謬之千里。八方圓融，一竅不通。大哉牛醫，斷送畜生。長埋地下，不再顯靈。」（梁容若〈差之毫釐謬之千里〉）"
