      "group": "【題組（第49～50題）】阮氏青河畢業於越南最高學府—河內大學，西元 2003 年她離鄉背井來到臺灣，在工廠擔任作業員。來臺工作幾年後，她因結識熱愛越南文化的臺灣老公而留在臺灣，婚後生了一兒一女。阮氏青河很重視小孩學習越南語及了解媽媽故鄉的文化。在家人的鼓勵與支持下，阮氏青河進入成功大學歷史系碩士班就讀，體貼的老公看在眼裡，主動跳出來一肩扛起照顧孩子的工作。經過將近十年的苦讀，阮氏青河成為炙手可熱的越南語老師。"
